                              "description": "e.g. '24px'"
                            },
                            "left": {
                              "type": "string",
                              "description": "e.g. '24px'"
                            }
                          },
                          "required": [
                            "top",
                            "right",
                            "bottom",
                            "left"
                          ]
                        },
                        "font_size": {
                          "type": "string"
                        },
