                        },
                        "button_background": {
                          "type": "string"
                        },
                        "button_text_color": {
                          "type": "string"
                        },
                        "button_padding_x": {
                          "type": "string"
                        },
                        "button_padding_y": {
                          "type": "string"
                        }
                      }
